export interface AccompHandle {
  /** Volume do acompanhamento inteiro (0 = mudo). */
  setGain(gain: number): void;
  /** Volume de um instrumento (0 = desligado). */
  setPartGain(part: AccompPart, gain: number): void;
  stop(): void;
}

/**
 * Acompanhamento tocado a partir da harmonia, no mesmo relógio das faixas e do metrônomo.
 * Agenda as notas com antecedência (janela de 0,3 s, renovada a cada 60 ms). Os instrumentos
 * desligados continuam agendados com volume 0: ligar no meio da música entra na hora.
 */
export function startAccompaniment(
  notesBetween: (from: number, to: number) => AccompNote[],
  startAtCtx: number,
  fromSongSec: number,
  gain: number,
  partGains: Readonly<Record<AccompPart, number>>,
): AccompHandle {
  const ctx = getAudioContext();
  const out = ctx.createGain();
  out.gain.value = gain;
  out.connect(masterOut());
  const parts = {} as Record<AccompPart, GainNode>;
  for (const p of Object.keys(partGains) as AccompPart[]) {
    const g = ctx.createGain();
    g.gain.value = partGains[p];
    g.connect(out);
    parts[p] = g;
  }
  const LOOKAHEAD = 0.3;
  let scheduledUntil = fromSongSec;
  const toCtx = (songSec: number) => startAtCtx + (songSec - fromSongSec);
  const sources = new Set<AudioScheduledSourceNode>();
  const pump = () => {
    const nowSong = fromSongSec + (ctx.currentTime - startAtCtx);
    const until = Math.max(scheduledUntil, nowSong) + LOOKAHEAD;
    for (const s of playAccompNotes(ctx, parts, notesBetween(scheduledUntil, until), toCtx, ctx.currentTime)) {
      sources.add(s);
      s.addEventListener('ended', () => sources.delete(s));
    }
    scheduledUntil = until;
  };
  pump();
  const timer = window.setInterval(pump, 60);
  return {
    setGain(g) {
      out.gain.setTargetAtTime(g, ctx.currentTime, 0.02);
    },
    setPartGain(p, g) {
      parts[p]?.gain.setTargetAtTime(g, ctx.currentTime, 0.02);
    },
    stop() {
      window.clearInterval(timer);
      for (const s of [...sources]) {
        try {
          s.stop();
        } catch {
          /* já encerrado */
        }
      }
      sources.clear();
      out.disconnect();
    },
  };
}

