/** MIDI do baixo (cache que o app lê antes de chamar o Basic Pitch): uma nota por tempo, na fundamental e na quinta. */
function bassMidi() {
  const ev = [];
  const vlq = (n) => {
    const b = [n & 0x7f];
    while ((n >>= 7)) b.unshift((n & 0x7f) | 0x80);
    return b;
  };
  let last = 0;
  const push = (tick, bytes) => {
    ev.push(...vlq(tick - last), ...bytes);
    last = tick;
  };
  push(0, [0xff, 0x51, 0x03, 0x07, 0xa1, 0x20]);
  for (let b = 0; b < BARS; b++) {
    const r = 28 + ((roots[b] - 4 + 12) % 12);
    for (let k = 0; k < 4; k++) {
      const note = k === 2 ? r + 7 : r;
      const t = (b * 4 + k) * 480;
      push(t, [0x90, note, 90]);
      push(t + 400, [0x80, note, 0]);
    }
  }
  push(last, [0xff, 0x2f, 0x00]);
  const trk = Buffer.from(ev);
  const head = Buffer.from([0x4d, 0x54, 0x68, 0x64, 0, 0, 0, 6, 0, 0, 0, 1, 0x01, 0xe0]);
  const th = Buffer.alloc(8);
  th.write('MTrk', 0);
  th.writeUInt32BE(trk.length, 4);
  return Buffer.concat([head, th, trk]);
}
